    HoodieTestUtils.writeRecordsToLogFiles(metaClient.getFs(), metaClient.getBasePath(), HoodieTestDataGenerator.avroSchema, updatedRecords);
    // Verify that all data file has one log file
    metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), basePath);
    table = HoodieTable.getHoodieTable(metaClient, config, jsc);
    for (String partitionPath : dataGen.getPartitionPaths()) {
        List<FileSlice> groupedLogFiles = table.getRTFileSystemView().getLatestFileSlices(partitionPath).collect(Collectors.toList());
        for (FileSlice fileSlice : groupedLogFiles) {
            assertEquals("There should be 1 log file written for every data file", 1, fileSlice.getLogFiles().count());
        }
    }
    // Mark 2nd delta-instant as completed
    metaClient.getActiveTimeline().saveAsComplete(new HoodieInstant(State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, newCommitTime), Optional.empty());
    // Do a compaction
    String compactionInstantTime = writeClient.scheduleCompaction(Optional.empty()).get().toString();
    JavaRDD<WriteStatus> result = writeClient.compact(compactionInstantTime);
    // Verify that recently written compacted data file has no log file
    metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), basePath);
    table = HoodieTable.getHoodieTable(metaClient, config, jsc);
    HoodieActiveTimeline timeline = metaClient.getActiveTimeline();
    assertTrue("Compaction commit should be > than last insert", HoodieTimeline.compareTimestamps(timeline.lastInstant().get().getTimestamp(), newCommitTime, HoodieTimeline.GREATER));
    for (String partitionPath : dataGen.getPartitionPaths()) {
        List<FileSlice> groupedLogFiles = table.getRTFileSystemView().getLatestFileSlices(partitionPath).collect(Collectors.toList());
        for (FileSlice slice : groupedLogFiles) {
            assertTrue("After compaction there should be no log files visiable on a Realtime view", slice.getLogFiles().collect(Collectors.toList()).isEmpty());
        }
        List<WriteStatus> writeStatuses = result.collect();
        assertTrue(writeStatuses.stream().filter(writeStatus -> writeStatus.getStat().getPartitionPath().contentEquals(partitionPath)).count() > 0);
    }
}

