@Test
public void testRollbackInflightIngestionWithPendingCompaction() throws Exception {
    // Rollback inflight ingestion when there is pending compaction
    HoodieWriteConfig cfg = getConfig(false);
    HoodieWriteClient client = new HoodieWriteClient(jsc, cfg, true);
    String firstInstantTime = "001";
    String secondInstantTime = "004";
    String compactionInstantTime = "005";
    String inflightInstantTime = "006";
    String nextInflightInstantTime = "007";
    int numRecs = 2000;
    List<HoodieRecord> records = dataGen.generateInserts(firstInstantTime, numRecs);
    records = runNextDeltaCommits(client, Arrays.asList(firstInstantTime, secondInstantTime), records, cfg, true, new ArrayList<>());
    // Schedule compaction but do not run them
    scheduleCompaction(compactionInstantTime, client, cfg);
    HoodieTableMetaClient metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
    createNextDeltaCommit(inflightInstantTime, records, client, metaClient, cfg, true);
    metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
    HoodieInstant pendingCompactionInstant = metaClient.getActiveTimeline().filterPendingCompactionTimeline().firstInstant().get();
    assertTrue("Pending Compaction instant has expected instant time", pendingCompactionInstant.getTimestamp().equals(compactionInstantTime));
    HoodieInstant inflightInstant = metaClient.getActiveTimeline().filterInflightsExcludingCompaction().firstInstant().get();
    assertTrue("inflight instant has expected instant time", inflightInstant.getTimestamp().equals(inflightInstantTime));
    //This should rollback
    client.startCommitWithTime(nextInflightInstantTime);
    //Validate
    metaClient = new HoodieTableMetaClient(jsc.hadoopConfiguration(), cfg.getBasePath());
    inflightInstant = metaClient.getActiveTimeline().filterInflightsExcludingCompaction().firstInstant().get();
    assertTrue("inflight instant has expected instant time", inflightInstant.getTimestamp().equals(nextInflightInstantTime));
    assertTrue("Expect only one inflight instant", metaClient.getActiveTimeline().filterInflightsExcludingCompaction().getInstants().count() == 1);
    //Expect pending Compaction to be present
    pendingCompactionInstant = metaClient.getActiveTimeline().filterPendingCompactionTimeline().firstInstant().get();
    assertTrue("Pending Compaction instant has expected instant time", pendingCompactionInstant.getTimestamp().equals(compactionInstantTime));
}

