/**
 * Testing converting array types to Hive field declaration strings, according to the Parquet-113
 * spec: https://github.com/apache/parquet-format/blob/master/LogicalTypes.md#lists
 */
@Test
public void testSchemaConvertArray() throws IOException {
    // Testing the 3-level annotation structure
    MessageType schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().optional(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("list").named("int_list").named("ArrayOfInts");
    String schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list` ARRAY< int>", schemaString);
    // A array of arrays
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().requiredGroup().as(OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("list").named("element").named("list").named("int_list_list").named("ArrayOfArrayOfInts");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list_list` ARRAY< ARRAY< int>>", schemaString);
    // A list of integers
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeated(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("int_list").named("ArrayOfInts");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list` ARRAY< int>", schemaString);
    // A list of structs with two fields
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").required(PrimitiveType.PrimitiveTypeName.INT32).named("num").named("element").named("tuple_list").named("ArrayOfTuples");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`tuple_list` ARRAY< STRUCT< `str` : binary, `num` : int>>", schemaString);
    // A list of structs with a single field
    // For this case, since the inner group name is "array", we treat the
    // element type as a one-element struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("array").named("one_tuple_list").named("ArrayOfOneTuples");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< STRUCT< `str` : binary>>", schemaString);
    // A list of structs with a single field
    // For this case, since the inner group name ends with "_tuple", we also treat the
    // element type as a one-element struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("one_tuple_list_tuple").named("one_tuple_list").named("ArrayOfOneTuples2");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< STRUCT< `str` : binary>>", schemaString);
    // A list of structs with a single field
    // Unlike the above two cases, for this the element type is the type of the
    // only field in the struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("one_tuple_list").named("one_tuple_list").named("ArrayOfOneTuples3");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< binary>", schemaString);
    // A list of maps
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().as(OriginalType.MAP).repeatedGroup().as(OriginalType.MAP_KEY_VALUE).required(PrimitiveType.PrimitiveTypeName.BINARY).as(OriginalType.UTF8).named("string_key").required(PrimitiveType.PrimitiveTypeName.INT32).named("int_value").named("key_value").named("array").named("map_list").named("ArrayOfMaps");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`map_list` ARRAY< MAP< string, int>>", schemaString);
}

@Test
public void testBasicSync() throws IOException, InitializationError, URISyntaxException, TException, InterruptedException {
